solution.solution.cpp:
#include <cstdint>
#include <map>
#include <string>
#include <vector>

using Memory = std::map<std::uint64_t, std::uint64_t>;
struct Symbol { std::uint32_t rva; std::string name; };
struct Module { std::string name; std::uint64_t base; std::uint32_t size; std::vector<Symbol> symbols; };

std::vector<std::uint64_t> walkStack(const Memory& m, std::uint64_t rip, std::uint64_t rbp, int maxFrames)
{
    std::vector<std::uint64_t> frames{ rip };
    while (rbp != 0 && static_cast<int>(frames.size()) < maxFrames)
    {
        const auto ret{ m.find(rbp + 8) }, saved{ m.find(rbp) };
        if (ret == m.end() || saved == m.end() || ret->second == 0) break;
        frames.push_back(ret->second);
        if (saved->second != 0 && saved->second <= rbp) break;
        rbp = saved->second;
    }
    return frames;
}

static std::string hex(std::uint64_t v)
{
    static const char* const HEX{ "0123456789abcdef" };
    std::string out;
    do { out.insert(out.begin(), HEX[v & 0xF]); v >>= 4; } while (v);
    return "0x" + out;
}

std::string describe(const std::vector<Module>& modules, std::uint64_t address)
{
    for (const Module& mod : modules)
    {
        if (address < mod.base || address - mod.base >= mod.size) continue;
        const std::uint32_t rva{ static_cast<std::uint32_t>(address - mod.base) };
        const Symbol* best{ nullptr };
        for (const Symbol& s : mod.symbols)
            if (s.rva <= rva && (!best || s.rva > best->rva)) best = &s;
        if (!best) return mod.name + "+" + hex(rva);
        return mod.name + "!" + best->name + (rva == best->rva ? "" : "+" + hex(rva - best->rva));
    }
    return hex(address);
}

unitTests:
// Three frames: main -> World::update -> Player::takeDamage, with rbp chains at 0x9F00 -> 0x9F60 -> 0x9FC0 -> 0
static Memory stack()
{
    return {
        { 0x9F00, 0x9F60 }, { 0x9F08, 0x7FF600001510 },
        { 0x9F60, 0x9FC0 }, { 0x9F68, 0x7FF600001050 },
        { 0x9FC0, 0 },      { 0x9FC8, 0x7FF6000004A0 },
    };
}
static std::vector<Module> modules()
{
    return {
        { "game.exe", 0x7FF600000000, 0x20000, { { 0x1500, "World::update" }, { 0x1000, "main" }, { 0x1800, "Player::takeDamage" } } },
        { "ntdll.dll", 0x7FFA00000000, 0x200000, {} },
    };
}

TEST("walking the chain") {
    const auto frames{ walkStack(stack(), 0x7FF600001814, 0x9F00, 10) };
    CHECK_EQ(frames, (std::vector<std::uint64_t>{ 0x7FF600001814, 0x7FF600001510, 0x7FF600001050, 0x7FF6000004A0 }));
    CHECK_EQ(walkStack(stack(), 0x7FF600001814, 0x9F00, 2).size(), 2u);
    CHECK_EQ(walkStack(stack(), 0x7FF600001814, 0, 10).size(), 1u);
}
TEST("broken chains stop cleanly") {
    Memory bad{ stack() };
    bad[0x9F60] = 0x9E00;
    const auto frames{ walkStack(bad, 0x1, 0x9F00, 10) };
    CHECK_EQ(frames.size(), 3u);
    CHECK_EQ(walkStack(Memory{}, 0x1, 0x9F00, 10).size(), 1u);
}
TEST("naming addresses") {
    const auto mods{ modules() };
    CHECK_EQ(describe(mods, 0x7FF600001814), std::string("game.exe!Player::takeDamage+0x14"));
    CHECK_EQ(describe(mods, 0x7FF600001510), std::string("game.exe!World::update+0x10"));
    CHECK_EQ(describe(mods, 0x7FF600001000), std::string("game.exe!main"));
    CHECK_EQ(describe(mods, 0x7FF6000004A0), std::string("game.exe+0x4a0"));
    CHECK_EQ(describe(mods, 0x7FFA00012345), std::string("ntdll.dll+0x12345"));
    CHECK_EQ(describe(mods, 0x12345678), std::string("0x12345678"));
}

